/**
 * Preview builder contract: the preview renders the generated bytes and
 * nothing else. Inertness of hostile content comes from the `sandbox=""`
 * iframe (asserted in the browser E2E); these unit tests pin what the
 * builder itself is allowed to do.
 */

import { describe, expect, it } from 'vitest';
import { buildPreviewSrcDoc, isPreviewableTarget } from './preview';

describe('preview builder', () => {
  it('accepts only targets a browser renders without a runtime', () => {
    expect(isPreviewableTarget('svg')).toBe(true);
    expect(isPreviewableTarget('html')).toBe(true);
    expect(isPreviewableTarget('tailwind')).toBe(false);
    expect(isPreviewableTarget('modules')).toBe(false);
    expect(isPreviewableTarget('flutter')).toBe(false);
    expect(isPreviewableTarget('swiftui')).toBe(false);
    expect(isPreviewableTarget('compose')).toBe(false);
  });

  it('renders SVG output as the exact document bytes', () => {
    const svg = '<svg xmlns="http://www.w3.org/2000/svg"><rect width="1" height="1"/></svg>';
    expect(buildPreviewSrcDoc('svg', { html: svg })).toBe(svg);
  });

  it('composes HTML pages from the emitted markup and stylesheet only', () => {
    const doc = buildPreviewSrcDoc('html', {
      html: '<main><h1>Hi</h1></main>',
      css: 'main { color: red; }',
    });
    expect(doc).toContain('<style>main { color: red; }</style>');
    expect(doc).toContain('<main><h1>Hi</h1></main>');
    // No editor chrome, no runtime, no scripts, no network references.
    expect(doc).not.toContain('<script');
    expect(doc).not.toContain('http://');
    expect(doc).not.toContain('https://');
  });

  it('passes hostile-but-harmless payloads through verbatim (the sandbox isolates, not the builder)', () => {
    const hostile = '<p>hello</p><script>window.top.location="https://evil.example"</script>';
    const doc = buildPreviewSrcDoc('html', { html: hostile, css: '' });
    // The builder does not execute, rewrite, or "sanitize" the markup: the
    // sandbox attribute on the consuming iframe is the security boundary,
    // and mutating generated output here would make the preview diverge
    // from the deliverable.
    expect(doc).toContain(hostile);
  });
});
